import json,re,collections,unicodedata
cal=json.load(open('calibre.json')); hc=json.load(open('hc_library.json'))
def norm(s):
    s=unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower()
    return re.sub(r'[^a-z0-9]+',' ',s).strip()
def main_title(s): return norm(re.split(r'[:(]',s)[0])
def isbn13(i):
    i=re.sub(r'[^0-9Xx]','',i or '')
    if len(i)==13:return i
    if len(i)==10:
        c='978'+i[:9];s=sum(int(x)*(1 if k%2==0 else 3) for k,x in enumerate(c));return c+str((10-s%10)%10)
def isbns(e):
    r=set()
    for k in('isbn_10','isbn_13'):
        v=isbn13((e or {}).get(k))
        if v:r.add(v)
    return r
byisbn=collections.defaultdict(set); bytitle=collections.defaultdict(list)
for u in hc:
    b=u['book']; ids=isbns(u['edition'])
    for e in b['editions'] or []: ids|=isbns(e)
    for i in ids: byisbn[i].add(b['id'])
    bytitle[main_title(b['title'])].append(u)
hcbook={u['book']['id']:u for u in hc}
def surnames(a): return {norm(x).split()[-1] for x in re.split(r'&|,| and ',a) if norm(x)}
res={};unm=[];amb=[]
for c in cal:
    ids=c.get('identifiers') or {}
    m=None;how=None
    ci=isbn13(ids.get('isbn'))
    if ci and len(byisbn[ci])==1: m=next(iter(byisbn[ci]));how='isbn'
    if m is None:
        cands=bytitle.get(main_title(c['title']),[])
        if len(cands)>1:
            f=[u for u in cands if surnames(c['authors'])&{norm(x).split()[-1] for x in (u['book']['cached_contributors'] and [a['author']['name'] for a in u['book']['cached_contributors'] if a.get('author')] or [])}]
            cands=f or cands
        if len(cands)==1: m=cands[0]['book']['id'];how='title'
        elif len(cands)>1: amb.append((c['id'],c['title'],len(cands)))
    if m: res[c['id']]=(m,how)
    elif not any(a[0]==c['id'] for a in amb): unm.append((c['id'],c['title']))
print('calibre',len(cal),'matched',len(res),collections.Counter(h for _,h in res.values()))
print('ambiguous',len(amb),'unmatched',len(unm))
dup=collections.Counter(m for m,_ in res.values());print('hc books matched by >1 calibre book:',[(hcbook[k]['book']['title'][:40],v) for k,v in dup.items() if v>1])
print('hc books with no calibre match:',len(set(hcbook)-set(dup)))
print('AMB',amb[:15]);print('UNM',unm[:25])
json.dump({str(k):{'id':v[0],'slug':hcbook[v[0]]['book']['slug'],'how':v[1]} for k,v in res.items()},open('matches.json','w'))
